import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class ContractTest{@Test void collisionsExactCodesAndEmpty(){String[]in={"Aa","BB","Aa"," ",""," A","A","a"};String[]old=in.clone();Object r=TaskBinding.count(in);assertEquals(Set.of("Aa","BB"," ",""," A","A","a"),TaskBinding.unique(r));assertEquals(Map.of("Aa",2,"BB",1," ",1,"",1," A",1,"A",1,"a",1),TaskBinding.counts(r));assertArrayEquals(old,in);assertEquals(1,TaskBinding.lookup(r,"BB"));assertTrue(TaskBinding.equal("Aa","Aa"));assertFalse(TaskBinding.equal("Aa","BB"));assertEquals(TaskBinding.hash("Aa"),TaskBinding.hash(new String("Aa")));Object empty=TaskBinding.count(new String[0]);assertTrue(TaskBinding.unique(empty).isEmpty());assertTrue(TaskBinding.counts(empty).isEmpty());}}
